import re

def solve(env, goal):
    def find(pattern, text):
        m = re.search(pattern, text, re.I)
        return m.group(1) if m else None

    def obj_type(name):
        return re.sub(r'\s+\d+$', '', name.strip().lower())

    goal_lower = goal.lower()

    # target object type (thing to heat)
    target_obj = None
    for m in re.finditer(r'heat (?:some |a |an )?([a-z]+)', goal_lower):
        target_obj = m.group(1)
        break
    if target_obj is None:
        # "heat some egg" style already handled; fallback
        m = re.search(r'(?:heat|warm)\s+(?:some\s+|a\s+|an\s+)?(\w+)', goal_lower)
        if m:
            target_obj = m.group(1)

    # destination receptacle type
    dest = None
    for m in re.finditer(r'(?:in|on|to)\s+(?:the\s+)?([a-z]+)', goal_lower):
        cand = m.group(1)
        if cand not in ('the', 'a', 'an') and cand != target_obj:
            dest = cand
    if dest is None:
        m = re.search(r'put .*?(?:in|on|to)\s+(?:the\s+)?(\w+)', goal_lower)
        if m:
            dest = m.group(1)

    def parse_receptacles(obs):
        return re.findall(r'\b([a-z]+)\s+(\d+)\b', obs.lower())

    def parse_objects(obs):
        return re.findall(r'\b([a-z]+)\s+(\d+)\b', obs.lower())

    def all_receptacles():
        obs = env.observation
        recs = []
        seen = set()
        for name, num in parse_receptacles(obs):
            key = (name, num)
            if key not in seen:
                seen.add(key)
                recs.append((name, num))
        return recs

    # Known receptacles from room description (stored in env.observation at start)
    room_desc = env.observation
    known_recs = []
    seen = set()
    for name, num in parse_receptacles(room_desc):
        key = (name, num)
        if key not in seen:
            seen.add(key)
            known_recs.append((name, num))

    def is_container(name):
        return name in ('drawer', 'cabinet', 'fridge', 'microwave', 'safe')

    def go_to(name, num):
        return env.step(f"go to {name} {num}")

    def open_rec(name, num):
        return env.step(f"open {name} {num}")

    def close_rec(name, num):
        return env.step(f"close {name} {num}")

    def take(obj, rec):
        return env.step(f"take {obj} from {rec}")

    def move(obj, rec):
        return env.step(f"move {obj} to {rec}")

    def heat(obj, rec):
        return env.step(f"heat {obj} with {rec}")

    def look():
        return env.step("look")

    def inventory():
        return env.step("inventory")

    def current_obs():
        return env.observation

    def extract_objects_from_obs(obs):
        # objects visible "On the X, you see a apple 2, ..." or "In it, you see ..."
        objs = []
        for m in re.finditer(r'(?:on|in|at)\s+(?:the\s+)?[a-z]+\s+\d+[^,]*?(?:you see|,)\s*([^\n]*)', obs, re.I):
            pass
        # simpler: find "you see" segments
        segs = re.findall(r'you see([^\n]*)', obs, re.I)
        for seg in segs:
            for name, num in parse_objects(seg):
                if name not in ('the', 'a', 'an', 'it', 'you', 'nothing') and (name, num) not in objs:
                    objs.append((name, num))
        return objs

    # Ensure we have a microwave identified
    microwave = None
    for name, num in known_recs:
        if name == 'microwave':
            microwave = (name, num)
            break

    # search for target object
    target = None
    visited = set()

    def explore_for_object():
        nonlocal target
        # First check current location
        obs = current_obs()
        objs = extract_objects_from_obs(obs)
        for name, num in objs:
            if obj_type(name) == target_obj:
                return (name, num)
        # Check inventory
        inv_obs = inventory()
        # inventory returns something like "You are carrying a egg 2."
        m = re.findall(r'\b([a-z]+)\s+(\d+)\b', inv_obs.lower())
        for name, num in m:
            if obj_type(name) == target_obj:
                return (name, num)
        # Go through all receptacles
        for name, num in known_recs:
            if (name, num) in visited:
                continue
            visited.add((name, num))
            if name in ('microwave','fridge') and is_container(name):
                # need to open to see
                go_to(name, num)
                obs = current_obs()
                if 'closed' in obs.lower():
                    open_rec(name, num)
                    obs = current_obs()
                objs = extract_objects_from_obs(obs)
                for oname, onum in objs:
                    if obj_type(oname) == target_obj:
                        return (oname, onum)
            else:
                go_to(name, num)
                obs = current_obs()
                objs = extract_objects_from_obs(obs)
                for oname, onum in objs:
                    if obj_type(oname) == target_obj:
                        return (oname, onum)
        return None

    # First try to find target object
    target = explore_for_object()

    if target is None:
        # Fallback: search more broadly by trying all known receptacles
        for name, num in known_recs:
            go_to(name, num)
            obs = current_obs()
            if is_container(name) and 'closed' in obs.lower():
                open_rec(name, num)
                obs = current_obs()
            objs = extract_objects_from_obs(obs)
            for oname, onum in objs:
                if obj_type(oname) == target_obj:
                    target = (oname, onum)
                    break
            if target:
                break

    if target is None:
        return "Could not find target object"

    # Take the object
    # Need to know which receptacle it's on
    # We'll go back: we know where we found it, but simpler: check inventory first
    inv_obs = inventory()
    on_hand = re.findall(r'\b([a-z]+)\s+(\d+)\b', inv_obs.lower())
    if not any(obj_type(n) == target_obj for n, _ in on_hand):
        # Need to find where it is: we tracked via explore, but we lost location.
        # Simplest: re-explore, and when found, take immediately
        for name, num in known_recs:
            go_to(name, num)
            obs = current_obs()
            if is_container(name) and 'closed' in obs.lower():
                open_rec(name, num)
                obs = current_obs()
            objs = extract_objects_from_obs(obs)
            for oname, onum in objs:
                if obj_type(oname) == target_obj:
                    take(oname, f"{name} {num}")
                    target = (oname, onum)
                    break
            if target:
                break

    # Now heat the object
    if microwave is None:
        # find microwave in current observation
        for name, num in parse_receptacles(current_obs()):
            if name == 'microwave':
                microwave = (name, num)
                break
    if microwave is None:
        # search room for microwave
        for name, num in known_recs:
            if name == 'microwave':
                microwave = (name, num)
                break

    if microwave:
        go_to(microwave[0], microwave[1])
        obs = current_obs()
        if 'closed' in obs.lower():
            open_rec(microwave[0], microwave[1])
        # heat
        # target object name and number
        # get from inventory
        inv_obs = inventory()
        on_hand = re.findall(r'\b([a-z]+)\s+(\d+)\b', inv_obs.lower())
        held = None
        for n, num in on_hand:
            if obj_type(n) == target_obj:
                held = f"{n} {num}"
                break
        if held:
            heat(held, f"{microwave[0]} {microwave[1]}")

    # Now go to destination receptacle
    # Find a receptacle of the destination type
    dest_rec = None
    for name, num in known_recs:
        if name == dest:
            dest_rec = (name, num)
            break

    # If not in known_recs, search room
    if dest_rec is None:
        for name, num in parse_receptacles(current_obs()):
            if name == dest:
                dest_rec = (name, num)
                break

    if dest_rec is None:
        # Try all receptacles
        for name, num in known_recs:
            if name == dest:
                dest_rec = (name, num)
                break

    if dest_rec:
        go_to(dest_rec[0], dest_rec[1])
        obs = current_obs()
        if is_container(dest_rec[0]) and 'closed' in obs.lower():
            open_rec(dest_rec[0], dest_rec[1])
        # move held object
        inv_obs = inventory()
        on_hand = re.findall(r'\b([a-z]+)\s+(\d+)\b', inv_obs.lower())
        held = None
        for n, num in on_hand:
            if obj_type(n) == target_obj:
                held = f"{n} {num}"
                break
        if held:
            move(held, f"{dest_rec[0]} {dest_rec[1]}")
        else:
            # try to take target again
            for name, num in known_recs:
                go_to(name, num)
                obs = current_obs()
                if is_container(name) and 'closed' in obs.lower():
                    open_rec(name, num)
                    obs = current_obs()
                objs = extract_objects_from_obs(obs)
                for oname, onum in objs:
                    if obj_type(oname) == target_obj:
                        take(oname, f"{name} {num}")
                        # now heat/move
                        heat(f"{oname} {onum}", f"{microwave[0]} {microwave[1]}") if microwave else None
                        move(f"{oname} {onum}", f"{dest_rec[0]} {dest_rec[1]}")
                        return
        if is_container(dest_rec[0]):
            close_rec(dest_rec[0], dest_rec[1])
    return
